package com.enterprise.procurement.persistence.entity;
import com.baomidou.mybatisplus.annotation.*; import java.time.LocalDateTime;
@TableName("approval_record") public class ApprovalRecordEntity { @TableId(type=IdType.AUTO) private Long id; private Long requestId; private Long approverId; private String action; private String comment; private LocalDateTime createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getRequestId(){return requestId;} public void setRequestId(Long v){requestId=v;} public Long getApproverId(){return approverId;} public void setApproverId(Long v){approverId=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getComment(){return comment;} public void setComment(String v){comment=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
